import com.tom_roush.pdfbox.rendering.PDFRenderer;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class PdfLayoutActivity extends BackHandlingActivity {
    private String path,password,name;private int count,current,size,orientation,align=1,start=1;private boolean numbers,total,busy,destroyed;private final java.util.concurrent.atomic.AtomicInteger generation=new java.util.concurrent.atomic.AtomicInteger();
    private float customW=210,customH=297;private final HashSet<Integer> selected=new HashSet<>();private File result;private ImageView preview;private TextView status,saveButton;private Bitmap bitmap;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());private Runnable scheduled;
    private ActivityResultLauncher<String> save;
    @Override public void onCreate(Bundle state){super.onCreate(state);PDFBoxResourceLoader.init(this);path=getIntent().getStringExtra("path");password=getIntent().getStringExtra("pdf_password");if(password==null)password="";name=getIntent().getStringExtra("name");if(name==null)name="Document";
        if(path==null){finish();return;}if(state!=null){current=state.getInt("page");size=state.getInt("size");orientation=state.getInt("orientation");align=state.getInt("align",1);start=state.getInt("start",1);numbers=state.getBoolean("numbers");total=state.getBoolean("total");customW=state.getFloat("width",210);customH=state.getFloat("height",297);ArrayList<Integer> pages=state.getIntegerArrayList("selected");if(pages!=null)selected.addAll(pages);String output=state.getString("result");if(output!=null&&new File(output).isFile())result=new File(output);}
        save=registerForActivityResult(new ActivityResultContracts.CreateDocument("application/pdf"),uri->{if(uri!=null)save(uri);});
        final boolean fresh=state==null;LinearLayout loading=new LinearLayout(this);loading.addView(new ProgressBar(this));setContentView(loading);if(!FolderLock.ensureDocument(this,path,()->load(fresh)))return;load(fresh);
    }
    private void load(boolean fresh){worker.execute(()->{try(PDDocument doc=PDDocument.load(new File(path),password)){int pages=doc.getNumberOfPages();if(pages==0)throw new IOException(UiText.get(R.string.ui_pdf_has_no_pages));runOnUiThread(()->{if(destroyed)return;count=pages;current=Math.min(current,count-1);if(fresh)for(int i=0;i<count;i++)selected.add(i);render();});}catch(Exception e){runOnUiThread(()->{toast(UiText.format(R.string.ui_cannot_open_pdf_value, e.getMessage()));finish();});}});}
    private void button(LinearLayout parent,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setEnabled(!busy);parent.addView(b);b.setOnClickListener(v->action.run());}
    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(android.widget.LinearLayout.VERTICAL);root.setBackgroundColor(AppTheme.background());button(root,UiText.get(R.string.ui_back_pdf_page_settings),this::handleBackPressed);ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(android.widget.LinearLayout.VERTICAL);body.setPadding(16,8,16,16);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        button(body,UiText.format(R.string.ui_pages_value_value, selected.size(), count),this::choosePages);
        String[] sizes={"Original","A4","A3","A5","Letter","Custom (mm)"};button(body,UiText.format(R.string.ui_size_value, UiText.label(sizes[size])),()->new ProtectedDialogs.Builder(this).setTitle(UiText.get(R.string.ui_page_size)).setItems(UiText.labels(sizes),(d,w)->{size=w;changed();render();}).show());
        if(size==5){LinearLayout custom=new LinearLayout(this);body.addView(custom);dimension(custom,"Width (mm)",customW,true);dimension(custom,"Height (mm)",customH,false);}
        button(body,UiText.format(R.string.ui_orientation_value, new String[]{"Keep","Portrait","Landscape"}[orientation]),()->new ProtectedDialogs.Builder(this).setTitle(UiText.get(R.string.ui_orientation)).setItems(new String[]{UiText.get(R.string.ui_keep), UiText.get(R.string.ui_portrait), UiText.get(R.string.ui_landscape)},(d,w)->{orientation=w;changed();render();}).show());
        CheckBox number=new CheckBox(this);number.setText(UiText.get(R.string.ui_add_page_numbers));number.setTextColor(AppTheme.ink());number.setEnabled(!busy);number.setChecked(numbers);body.addView(number);number.setOnCheckedChangeListener((b,value)->{numbers=value;changed();render();});
        if(numbers){button(body,UiText.format(R.string.ui_position_value, new String[]{"Left","Center","Right"}[align]),()->new ProtectedDialogs.Builder(this).setTitle(UiText.get(R.string.ui_footer_position)).setItems(new String[]{UiText.get(R.string.ui_left), UiText.get(R.string.ui_center), UiText.get(R.string.ui_right)},(d,w)->{align=w;changed();render();}).show());EditText first=new EditText(this);first.setText(String.format(Locale.getDefault(),"%d",start));first.setHint(UiText.get(R.string.ui_first_document_page_number));first.setInputType(2);first.setTextColor(AppTheme.ink());first.setHintTextColor(AppTheme.muted());first.setEnabled(!busy);body.addView(first);first.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){try{start=Integer.parseInt(s.toString());}catch(Exception ignored){start=0;}changed();}public void afterTextChanged(Editable e){}});CheckBox totals=new CheckBox(this);totals.setText(UiText.get(R.string.ui_show_final_page_number_x_total));totals.setTextColor(AppTheme.ink());totals.setEnabled(!busy);totals.setChecked(total);body.addView(totals);totals.setOnCheckedChangeListener((b,value)->{total=value;changed();});}
        TextView hint=new TextView(this);hint.setText(UiText.get(R.string.ui_a_new_copy_keeps_every_page_changes_apply_only_to_selected_pages_numbers_fo));hint.setTextColor(AppTheme.muted());body.addView(hint);
        LinearLayout navigation=new LinearLayout(this);body.addView(navigation);button(navigation,"‹",()->{if(current>0){current--;requestPreview();}});status=new TextView(this);status.setTextColor(AppTheme.ink());status.setGravity(Gravity.CENTER);navigation.addView(status,new LinearLayout.LayoutParams(0,-2,1));button(navigation,"›",()->{if(current+1<count){current++;requestPreview();}});
        preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(preview,new LinearLayout.LayoutParams(-1,Math.round(390*getResources().getDisplayMetrics().density)));
        if(result!=null){button(body,UiText.get(R.string.ui_open_result),()->startActivity(new Intent(this,PdfViewerActivity.class).putExtra("path",result.getAbsolutePath()).putExtra("name",name+" · page settings").putExtra("pdf_password",password)));button(body,UiText.get(R.string.ui_save_to_documents),()->{startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("document_action","Register").putExtra("path",result.getAbsolutePath()).putExtra("name",name+" · page settings").putExtra("pages",count).putExtra("origin_path",path));finish();});}
        saveButton=new TextView(this);saveButton.setText(busy ? UiText.get(R.string.ui_creating_pdf) : result==null ? UiText.get(R.string.ui_create_pdf) : UiText.get(R.string.ui_save_to_device));saveButton.setTextColor(AppTheme.onAccent());saveButton.setGravity(Gravity.CENTER);saveButton.setTextSize(17);saveButton.setBackgroundColor(AppTheme.accent());saveButton.setEnabled(!busy);root.addView(saveButton,new LinearLayout.LayoutParams(-1,Math.round(54*getResources().getDisplayMetrics().density)));saveButton.setOnClickListener(v->{if(result!=null)save.launch(name+"-pages.pdf");else create();});UiInsets.applyKeyboardAware(root);setContentView(root);FolderLock.guard(this,path);requestPreview();
    }
    private void dimension(LinearLayout row,String label,float value,boolean width){EditText input=new EditText(this);input.setHint(label);input.setTextColor(AppTheme.ink());input.setHintTextColor(AppTheme.muted());input.setEnabled(!busy);input.setContentDescription(label);input.setText(String.format(Locale.ROOT,"%.1f",value));input.setInputType(8194);row.addView(input,new LinearLayout.LayoutParams(0,-2,1));input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){float value=0;try{value=Float.parseFloat(s.toString().replace(',','.'));}catch(Exception ignored){}if(width)customW=value;else customH=value;changed();}public void afterTextChanged(Editable e){}});}
    private PdfPageLayout.Options options(){PdfPageLayout.Options o=new PdfPageLayout.Options();float[][] dimensions={{0,0},{595.276f,841.89f},{841.89f,1190.551f},{419.528f,595.276f},{612,792},{customW*72/25.4f,customH*72/25.4f}};o.width=dimensions[size][0];o.height=dimensions[size][1];o.orientation=orientation;o.numbers=numbers;o.total=total;o.align=align;o.start=start;o.selected.addAll(selected);return o;}
    private boolean valid(){return !selected.isEmpty()&&(!numbers||start>=1&&start<=1000000)&&(size!=5||Float.isFinite(customW)&&Float.isFinite(customH)&&customW>=20&&customH>=20&&customW<=2000&&customH<=2000);}
    private void changed(){result=null;generation.incrementAndGet();if(scheduled!=null)handler.removeCallbacks(scheduled);scheduled=this::requestPreview;handler.postDelayed(scheduled,300);if(saveButton!=null)saveButton.setText(UiText.get(R.string.ui_create_pdf));}
    private void choosePages(){String[] names=new String[count];boolean[] checked=new boolean[count];for(int i=0;i<count;i++){names[i]="Page "+(i+1);checked[i]=selected.contains(i);}androidx.appcompat.app.AlertDialog dialog=new ProtectedDialogs.Builder(this).setTitle(UiText.get(R.string.ui_apply_changes_to_pages)).setMultiChoiceItems(names,checked,(d,w,value)->checked[w]=value).setNegativeButton(UiText.get(R.string.ui_cancel),null).setNeutralButton(UiText.get(R.string.ui_select_clear_all),null).setPositiveButton(UiText.get(R.string.ui_apply),(d,w)->{selected.clear();for(int i=0;i<count;i++)if(checked[i])selected.add(i);changed();render();}).create();dialog.setOnShowListener(d->dialog.getButton(-3).setOnClickListener(v->{boolean all=true;for(boolean value:checked)all&=value;for(int i=0;i<count;i++){checked[i]=!all;dialog.getListView().setItemChecked(i,!all);}}));dialog.show();}
    private void requestPreview(){if(destroyed||busy||preview==null)return;int token=generation.incrementAndGet(),page=current;if(!valid()){status.setText(UiText.get(R.string.ui_select_pages_and_valid_dimensions_numbering));preview.setImageDrawable(null);return;}status.setText(UiText.format(R.string.ui_page_value_valuevalue, (page+1), count, (selected.contains(page)?" · selected":" · unchanged")));PdfPageLayout.Options settings=options();worker.execute(()->{if(token!=generation.get()||destroyed)return;try(PDDocument doc=PDDocument.load(new File(path),password)){PdfPageLayout.apply(doc,page,settings);com.tom_roush.pdfbox.pdmodel.common.PDRectangle box=doc.getPage(page).getCropBox();Bitmap image=new PDFRenderer(doc).renderImage(page,Math.min(1000/box.getWidth(),1400/box.getHeight()));runOnUiThread(()->{if(destroyed||token!=generation.get()){image.recycle();return;}preview.setImageBitmap(image);if(bitmap!=null)bitmap.recycle();bitmap=image;});}catch(Exception|OutOfMemoryError e){runOnUiThread(()->{if(!destroyed&&token==generation.get())status.setText(UiText.format(R.string.ui_preview_unavailable_value, e.getMessage()));});}});}
    private void create(){if(!valid()){toast(UiText.get(R.string.ui_select_pages_and_valid_dimensions_numbering));return;}if(!FolderLock.ensureDocument(this,path,this::create))return;PdfPageLayout.Options settings=options();busy=true;generation.incrementAndGet();setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LOCKED);render();worker.execute(()->{File output=new File(DocumentDirectories.documents(this),"page-layout-"+UUID.randomUUID()+".pdf");try(PDDocument doc=PDDocument.load(new File(path),password)){if(!doc.getCurrentAccessPermission().canModify())throw new IOException(UiText.get(R.string.ui_this_pdf_does_not_allow_changes));for(int i=0;i<doc.getNumberOfPages();i++){if(destroyed||Thread.currentThread().isInterrupted())throw new InterruptedIOException(UiText.get(R.string.ui_cancelled));PdfPageLayout.apply(doc,i,settings);}PdfProtection.inherit(doc,doc,password);doc.save(output);DocumentStore.inheritProtection(this,output.getAbsolutePath(),Collections.singletonList(path));runOnUiThread(()->{busy=false;result=output;setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);if(!destroyed)render();});}catch(Exception|OutOfMemoryError e){output.delete();runOnUiThread(()->{busy=false;setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);if(!destroyed){render();toast(UiText.format(R.string.ui_could_not_create_pdf_value, e.getMessage()));}});}});}
    private void save(Uri uri){if(result==null||busy)return;if(!FolderLock.ensureDocument(this,path,()->save(uri)))return;File file=result;busy=true;render();worker.execute(()->{String message=UiText.get(R.string.ui_saved_to_device);try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException(UiText.get(R.string.ui_destination_unavailable));byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}catch(Exception e){message=UiText.format(R.string.ui_could_not_save_value, e.getMessage());}String notice=message;runOnUiThread(()->{busy=false;if(!destroyed){render();toast(notice);}});});}
    @Override protected void onResume(){super.onResume();if(path!=null)FolderLock.guard(this,path);}
    @Override public void handleBackPressed(){if(busy){toast(UiText.get(R.string.ui_please_wait_for_saving_to_finish));return;}super.handleBackPressed();}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("page",current);b.putInt("size",size);b.putInt("orientation",orientation);b.putInt("align",align);b.putInt("start",start);b.putBoolean("numbers",numbers);b.putBoolean("total",total);b.putFloat("width",customW);b.putFloat("height",customH);b.putIntegerArrayList("selected",new ArrayList<>(selected));if(result!=null)b.putString("result",result.getAbsolutePath());}
    @Override protected void onDestroy(){destroyed=true;generation.incrementAndGet();handler.removeCallbacksAndMessages(null);worker.shutdownNow();preview=null;if(bitmap!=null)bitmap.recycle();super.onDestroy();}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
}
